# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SAHABE (ASHÂB) KAVRAMI, İLK MÜSLÜMANLAR (SÂBİKÛN-İ EVVELÛN) VE DÂRÜLERKAM</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Sahabe (Ashâb) Kimdir?</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Peygamberimiz Hz. Muhammed\'i</text>\n  <text x="40" y="114" font-size="11" fill="#334155">  (sav) mümin olarak gören,</text>\n  <text x="40" y="130" font-size="11" fill="#334155">  sohbetinde bulunan ve imanla</text>\n  <text x="40" y="146" font-size="11" fill="#334155">  vefat eden arkadaşlarıdır.</text>\n  <text x="40" y="170" font-size="11" fill="#334155">• Çoğulu: Ashâb / Sahâbe</text>\n  <text x="40" y="192" font-size="11" fill="#334155">• Mekke\'den göç edenler: Muhacir</text>\n  <text x="130" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Dostluk · İtimat · Sadakat</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. İlk Müslümanlar (İlk Dörtler)</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Kadınlardan: Hz. Hatice (ra)</text>\n  <text x="260" y="120" font-size="11" fill="#334155">• Çocuklardan: Hz. Ali (ra)</text>\n  <text x="260" y="142" font-size="11" fill="#334155">• Azatlılardan: Hz. Zeyd b. Hârise</text>\n  <text x="260" y="164" font-size="11" fill="#334155">• Hür Erkeklerden: Hz. Ebû Bekir</text>\n  <text x="260" y="186" font-size="11" fill="#334155">  (es-Sıddîk) ve onun vesilesiyle</text>\n  <text x="260" y="202" font-size="11" fill="#334155">  Hz. Osman, Zübeyr, Talha, Sa\'d.</text>\n  <text x="350" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Sâbikûn-i Evvelûn (İlk Öncüler)</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Dârülerkam (Erkam\'ın Evi)</text>\n  <text x="480" y="98" font-size="11" fill="#334155">• Genç sahabi Erkam b. Ebi\'l-Erkam</text>\n  <text x="480" y="114" font-size="11" fill="#334155">  evini İslam tebliğine açtı.</text>\n  <text x="480" y="136" font-size="11" fill="#334155">• Safa Tepesi eteğinde, Kâbe\'ye</text>\n  <text x="480" y="152" font-size="11" fill="#334155">  yakın ve güvenli bir konumdaydı.</text>\n  <text x="480" y="174" font-size="11" fill="#334155">• İslam\'ın ilk eğitim, Kur\'an öğretimi</text>\n  <text x="480" y="190" font-size="11" fill="#334155">  ve tebliğ merkezi oldu.</text>\n  <text x="570" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Hz. Ömer Burada Müslüman Oldu</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN MEKKELİ SAHABİLERLE İLETİŞİM İLKELERİ (PH.7.2.1)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">İletişim Dili ve Gönül Bağı</text>\n  <text x="44" y="100" font-size="11.5" fill="#334155">• Güvene Dayalı Samimiyet (İtimat): Her</text>\n  <text x="54" y="116" font-size="11" fill="#475569">sahabiye değer vermiş, yüzüne tebessümle</text>\n  <text x="54" y="132" font-size="11" fill="#475569">ve bütün vücuduyla dönerek dinlemiştir.</text>\n  <text x="44" y="156" font-size="11.5" fill="#334155">• Eşitlik ve Kardeşlik: Zengin-yoksul, hür-</text>\n  <text x="54" y="172" font-size="11" fill="#475569">köle (Bilâl-i Habeşî, Habbâb, Suheyb) ayrımı</text>\n  <text x="54" y="188" font-size="11" fill="#475569">yapmadan aynı sofrada ve mecliste oturmuştur.</text>\n  <text x="183" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Tatlı Dil · İstişare · Vefa · Şefkat</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Zorluklar Karşısında Moral ve Destek</text>\n  <text x="378" y="100" font-size="11.5" fill="#334155">• İşkence gören Yâsir ailesine: "Sabredin</text>\n  <text x="388" y="116" font-size="11" fill="#475569">ey Yâsir ailesi! Vaadiniz cennettir" müjdesi.</text>\n  <text x="378" y="140" font-size="11.5" fill="#334155">• Hz. Ebû Bekir\'in Bilâl-i Habeşî ve Âmir b.</text>\n  <text x="388" y="156" font-size="11" fill="#475569">Füheyre gibi mazlumları satın alıp azat etmesi.</text>\n  <text x="378" y="180" font-size="11.5" fill="#334155">• Mazlum sahabileri Habeşistan\'daki adil</text>\n  <text x="388" y="196" font-size="11" fill="#475569">hükümdar Necaşi\'nin ülkesine hicrete yönlendirmesi.</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Sabır · Fedakârlık · Merhamet</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MEKKELİ SAHABİLERİN SADAKATİ VE FEDAKÂRLIK ÖRNEKLERİ</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hz. Ebû Bekir (es-Sıddîk)</text>\n  <text x="40" y="100" font-size="11" fill="#334155">• Miraç hadisesini tereddütsüz</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  onaylayarak \'Sıddîk\' unvanını aldı.</text>\n  <text x="40" y="140" font-size="11" fill="#334155">• Servetini İslam ve mazlum köleleri</text>\n  <text x="40" y="156" font-size="11" fill="#334155">  özgürleştirmek için harcadı.</text>\n  <text x="40" y="180" font-size="11" fill="#334155">• Sevr Mağarası\'nda ve hicrette</text>\n  <text x="40" y="196" font-size="11" fill="#334155">  Peygamberimizin yol arkadaşı oldu.</text>\n  <text x="130" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Sarsılmaz Sadakat: Sıddîk</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Mus\'ab b. Umeyr (İlk Öğretmen)</text>\n  <text x="260" y="100" font-size="11" fill="#334155">• Mekke\'nin en varlıklı ve zarif</text>\n  <text x="260" y="116" font-size="11" fill="#334155">  genciyken ailesinin baskısına</text>\n  <text x="260" y="132" font-size="11" fill="#334155">  rağmen imanından vazgeçmedi.</text>\n  <text x="260" y="156" font-size="11" fill="#334155">• Dünya zenginliğini elinin tersiyle</text>\n  <text x="260" y="172" font-size="11" fill="#334155">  itip İslam\'ın ilk öğretmeni olarak</text>\n  <text x="260" y="188" font-size="11" fill="#334155">  Medine\'ye gönderildi.</text>\n  <text x="350" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Fedakârlık ve İlim Aşkı</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="570" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Bilâl-i Habeşî ve Sümeyye (ra)</text>\n  <text x="480" y="100" font-size="11" fill="#334155">• Kızgın kumlar altında \'Ehad!\'</text>\n  <text x="480" y="116" font-size="11" fill="#334155">  (Allah birdir) diyerek tevhidi</text>\n  <text x="480" y="132" font-size="11" fill="#334155">  haykıran Bilâl ilk müezzin oldu.</text>\n  <text x="480" y="156" font-size="11" fill="#334155">• Yâsir ve eşi Sümeyye (ra) İslam</text>\n  <text x="480" y="172" font-size="11" fill="#334155">  tarihinin ilk şehitleri olarak</text>\n  <text x="480" y="188" font-size="11" fill="#334155">  iman uğrunda canlarını verdiler.</text>\n  <text x="570" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Sabır ve İman Kararlılığı</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
